//! The results that fail today, each with the ticket whose fix makes it pass.
//!
//! The tickets, and the reason each of their results fails:
//! - `BIND/A3` (FU-26, FU-32/D1): the converter reads a quantifier over an anonymous variable as
//!   binding every anonymous variable of its body, and drops the binder's own variable and sort;
//!   the alpha-variant that names each `_` apart binds exactly the binder's own variable. This
//!   includes a function competitor's own axiom (an anonymous binder's sort annotation,
//!   `#Exists _:Bool . ...`, is lost as well), the competitors of the `owise` cross product,
//!   claims, and the search route (`search-anon-*`, and `search-macro-anon`, where the macro's
//!   binder captures the use site's `_`).
//! - `BIND/A4` (FU-33/D2): existential lifting reads the `?` variables of the right side and the
//!   `ensures` through their binders. On an anonymous `?_` binder the outer binder is vacuous and
//!   the kompile invariant K3 panics, so the base itself fails (rules and claims); on a named `?`
//!   binder beside a free right-side `?Y` the outer existentials follow the spellings, and a
//!   `?` binder renamed apart from `?Y` is lifted as well.
//! - `BIND/A5` (FU-34/D3, FU-39): the definition check treats a binder as binding its name in the
//!   whole sentence, so a right-side variable spelled like an `ensures` binder passes the check;
//!   and the parser's sort inference gives one name one sort across scopes, so a binder spelled
//!   like the left side's variable or a sibling binder takes that variable's sort (the source
//!   twins `text-shadow-*`, which then compile to a wrongly sorted binder or are refused), and a
//!   base with one name bound at two sorts in separate scopes does not load.
//! - `BIND/A6` (FU-35/D4, FU-36/D5, and the name maps after them): passes apply one name map to
//!   a whole sentence, so a binder that shadows another variable of its sentence is captured:
//!   macro substitution replaces a parameter under a macro binder of the same name (`macro`,
//!   `macro-rec`, `alias`), `minimize term construction` replaces a subterm of the left side
//!   under a binder that rebinds one of its variables (in rewrite, `anywhere`, `simplification`
//!   and function rules, under `#Not` and `#Or`), `resolve semantic casts` collects a variable's
//!   cast bounds by spelling across scopes (`binder-capture-any-sort`: "incomparable cast
//!   bounds", or a binder cast at the shadowed variable's sort), and the search route's sort
//!   predicates read a bound name as the free variable of that spelling (`search-named-capture`).
//!   The rule `UNIQUE_ID` digest numbers variables by spelling (`number_sentences.rs`), so a
//!   shadowing binder renamed apart, a variable named in an attribute (`concrete(X)`), or a
//!   `#let`/`#fun` whose minted label carries a variable's spelling changes the identifier of an
//!   alpha-equivalent rule (kind `Id`).
//! - `BIND/A7` (FU-37/D6): the strictness and context sentences place the minted `K<i>` and
//!   `HERE` beside a context alias's variables without renaming them apart, so an alias variable
//!   spelled `K<i>` merges with a strictness variable; and fresh constants take their counter
//!   offsets in the order of their spellings (`fresh-variables`).
//! - `unassigned`: no BIND ticket covers these. The search route orders the sort-membership
//!   conjuncts of a pattern's free variables by spelling (`search-macro-named-apart`): the two
//!   patterns mean the same, and their KORE is not alpha-equivalent.

pub use super::harness::Kind;

/// The fixed texts of the reports: the kinds' templates and the labels of a signature. A needle
/// made of these alone binds an entry to its kind and nothing more.
const GENERIC: &[&str] = &[
    "the base panics",
    "the variant panics",
    "load panics",
    "load refused",
    "the base compiles and the variant is refused",
    "the base is refused",
    "and the variant compiles",
    "is alpha-equivalent, and its UNIQUE_ID differs",
    "UNIQUE_ID not alpha-invariant",
    "UNIQUE_ID differs",
    "UNIQUE_ID",
    "could not parse rule",
    "the compiled search patterns differ",
    "differs:",
    "variant refused",
    "base refused",
    "variant pattern",
    "base pattern",
    "pattern: base",
    "base:",
    "variant:",
    "variant",
    "base",
    "under all",
    "under any",
    "run ",
    "at: ",
    "sentence",
    "-heat",
    "MACROS",
    "K3",
];

/// Whether `needle` is specific: at least 12 characters, of which something beyond the fixed
/// texts of the reports ([`GENERIC`]) is a name or a number.
pub fn needle_is_specific(needle: &str) -> bool {
    let mut rest = needle.to_owned();
    for generic in GENERIC {
        rest = rest.replace(generic, " ");
    }
    needle.chars().count() >= 12 && rest.chars().filter(|c| c.is_alphanumeric()).count() >= 2
}

/// One expected failure: the case, the strategy (`*` for a failure of the base itself), the
/// ticket, the kind of failure and a text the failure's report holds.
pub struct Expected {
    pub case: &'static str,
    pub strategy: &'static str,
    pub ticket: &'static str,
    pub kind: Kind,
    pub needle: &'static str,
}

impl Expected {
    pub fn key(&self) -> String {
        format!("{} {}", self.case, self.strategy)
    }
}

const fn expected(
    case: &'static str,
    strategy: &'static str,
    ticket: &'static str,
    kind: Kind,
    needle: &'static str,
) -> Expected {
    Expected {
        case,
        strategy,
        ticket,
        kind,
        needle,
    }
}

